var e=[{id:`ENAV`,nome:`Exame Nacional de Avaliação`,regiao:`Nacional`},{id:`CESPE`,nome:`Centro de Seleção e de Promoção de Eventos`,regiao:`Nacional`},{id:`FCC`,nome:`Fundação Carlos Chagas`,regiao:`Sudeste`},{id:`VUNESP`,nome:`Vunesp`,regiao:`Sudeste`},{id:`AVAMEC`,nome:`Associação dos Médicos Veterinários do Estado do Ceará`,regiao:`Nordeste`},{id:`CRMV`,nome:`Conselho Regional de Medicina Veterinária`,regiao:`Nacional`},{id:`UFMG`,nome:`Universidade Federal de Minas Gerais`,regiao:`Sudeste`},{id:`UNESP`,nome:`Universidade Estadual Paulista`,regiao:`Sudeste`},{id:`USP`,nome:`Universidade de São Paulo`,regiao:`Sudeste`},{id:`UFRRJ`,nome:`Universidade Federal Rural do Rio de Janeiro`,regiao:`Sudeste`},{id:`MAPA`,nome:`Ministério da Agricultura, Pecuária e Abastecimento`,regiao:`Nacional`}],t=[{id:`objetiva`,descricao:`Múltipla escolha`},{id:`certo_errado`,descricao:`Certo ou Errado`},{id:`discursiva`,descricao:`Discursiva`},{id:`multipla`,descricao:`Múltipla escolha com mais de uma alternativa`}],n=[{id:`principios_bioeticos`,nome:`Princípios Bioéticos`,descricao:`Autonomia, beneficência, não-maleficência e justiça na prática veterinária`,totalQuestoes:13},{id:`etica_profissional`,nome:`Ética Profissional`,descricao:`Código de Ética do Médico Veterinário, responsabilidade e deveres profissionais`,totalQuestoes:13},{id:`experimentacao_animal`,nome:`Experimentação Animal`,descricao:`Princípios dos 3Rs, CEUA e legislação sobre uso de animais em pesquisa`,totalQuestoes:13},{id:`eutanasia`,nome:`Eutanásia`,descricao:`Indicações, métodos, critérios éticos, legislação e bem-estar animal`,totalQuestoes:13},{id:`consentimento_informado`,nome:`Consentimento Informado`,descricao:`Dever de informar, autonomia do proprietário e comunicação de riscos`,totalQuestoes:13},{id:`conflitos_eticos`,nome:`Conflitos Éticos`,descricao:`Interesse do animal versus proprietário, eutanásia por conveniência`,totalQuestoes:13},{id:`responsabilidade_civil`,nome:`Responsabilidade Civil`,descricao:`Erro médico veterinário, negligência, imperícia e imprudência`,totalQuestoes:13},{id:`pesquisa_com_animais`,nome:`Pesquisa com Animais`,descricao:`Protocolos de pesquisa, ética em pesquisa e publicação científica`,totalQuestoes:12},{id:`ensino_com_animais`,nome:`Ensino com Animais`,descricao:`Uso didático de animais, simuladores e métodos alternativos`,totalQuestoes:12},{id:`relacao_medico_proprietario`,nome:`Relação Médico-Proprietário`,descricao:`Comunicação, empatia e limites na relação profissional`,totalQuestoes:12},{id:`bioetica_ambiental`,nome:`Bioética Ambiental`,descricao:`Impacto ambiental, sustentabilidade e fauna silvestre`,totalQuestoes:12},{id:`dilemas_contemporaneos`,nome:`Dilemas Contemporâneos`,descricao:`Terapia gênica, clonagem, organismos transgênicos`,totalQuestoes:12}],r=[{id:`bioet-014`,topico:`principios_bioeticos`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`Segundo os princípios da bioética de Beauchamp e Childress, qual princípio estabelece que o profissional deve agir sempre em benefício do paciente?`,alternativas:[`A) Autonomia`,`B) Beneficência`,`C) Não-maleficência`,`D) Justiça`,`E) Verdade`],gabarito:`B`,explicacao:`O princípio da beneficência determina que o profissional deve agir sempre visando o bem-estar e benefício do paciente.`},{id:`bioet-015`,topico:`principios_bioeticos`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`O princípio da não-maleficência, na prática veterinária, está relacionado principalmente a:`,alternativas:[`A) Respeitar a decisão do proprietário sobre o tratamento`,`B) Não causar dano ou sofrimento desnecessário ao animal`,`C) Garantir acesso igualitário aos serviços veterinários`,`D) Promover intervenções que maximizem o bem-estar`,`E) Informar o proprietário sobre riscos do procedimento`],gabarito:`B`,explicacao:`A não-maleficência (primum non nocere) determina que o profissional deve evitar causar dano ou sofrimento desnecessário ao paciente.`},{id:`bioet-016`,topico:`principios_bioeticos`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`Na bioética veterinária, o princípio da justiça está mais diretamente relacionado a:`,alternativas:[`A) Respeitar a autonomia do proprietário na escolha do tratamento`,`B) Garantir distribuição equitativa de recursos e cuidados veterinários`,`C) Evitar causar sofrimento desnecessário aos animais`,`D) Agir sempre em benefício do paciente animal`,`E) Obter consentimento antes de procedimentos`],gabarito:`B`,explicacao:`O princípio da justiça refere-se à distribuição equitativa de recursos, benefícios e encargos na prática veterinária.`},{id:`bioet-017`,topico:`principios_bioeticos`,banca:`VUNESP`,ano:2022,dificuldade:`facil`,enunciado:`O princípio bioético da autonomia, aplicado à Medicina Veterinária, refere-se:`,alternativas:[`A) À independência do médico veterinário em suas decisões`,`B) Ao direito do proprietário de decidir sobre o tratamento do animal após informações adequadas`,`C) À liberdade do animal de escolher seu próprio tratamento`,`D) À autonomia financeira do profissional`,`E) À independência do clínico em relação ao proprietário`],gabarito:`B`,explicacao:`Na veterinária, a autonomia é exercida indiretamente pelo proprietário/tutor, que deve tomar decisões informadas sobre o cuidado do animal.`},{id:`bioet-018`,topico:`principios_bioeticos`,banca:`AVAMEC`,ano:2023,dificuldade:`dificil`,enunciado:`Em uma situação em que o proprietário deseja eutanasiar um animal por motivos financeiros, mas o animal possui bom prognóstico com tratamento acessível, qual(is) princípio(s) bioético(s) entra(m) em conflito?`,alternativas:[`A) Apenas beneficência e não-maleficência`,`B) Autonomia do proprietário e beneficência em relação ao animal`,`C) Apenas justiça`,`D) Não-maleficência e justiça`,`E) Todos os quatro princípios simultaneamente`],gabarito:`B`,explicacao:`Há conflito entre a autonomia do proprietário (direito de decidir) e a beneficência (dever de agir em prol do animal que tem bom prognóstico).`},{id:`bioet-019`,topico:`principios_bioeticos`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`A dupla face do princípio da não-maleficência na veterinária inclui:`,alternativas:[`A) Não causar dano e não omitir socorro quando possível`,`B) Não causar dano e respeitar a autonomia do proprietário`,`C) Não causar dano e garantir justiça no atendimento`,`D) Não causar dano e informar sobre riscos`,`E) Não causar dano e promover a beneficência`],gabarito:`A`,explicacao:`A não-maleficência tem dupla face: não causar dano (ação) e não omitir assistência quando é possível ajudar (omissão).`},{id:`bioet-020`,topico:`principios_bioeticos`,banca:`UFMG`,ano:2021,dificuldade:`dificil`,enunciado:`Quando os princípios bioéticos entram em conflito na prática veterinária, a literatura recomenda que:`,alternativas:[`A) O princípio da autonomia sempre prevalece sobre os demais`,`B) Deve-se analisar caso a caso, ponderando os princípios e buscando a melhor solução`,`C) A não-maleficência sempre prevalece sobre a beneficência`,`D) O profissional deve seguir rigidamente o princípio da justiça`,`E) A autonomia do animal prevalece sobre a do proprietário`],gabarito:`B`,explicacao:`Não existe hierarquia fixa entre os princípios bioéticos; cada caso deve ser analisado individualmente, ponderando os princípios em conflito.`},{id:`bioet-021`,topico:`principios_bioeticos`,banca:`UNESP`,ano:2023,dificuldade:`facil`,enunciado:`Os quatro princípios fundamentais da bioética, propostos por Beauchamp e Childress, são:`,alternativas:[`A) Autonomia, Beneficência, Não-maleficência e Verdade`,`B) Autonomia, Beneficência, Não-maleficência e Justiça`,`C) Autonomia, Beneficência, Sigilo e Justiça`,`D) Beneficência, Não-maleficência, Justiça e Solidariedade`,`E) Autonomia, Não-maleficência, Justiça e Dignidade`],gabarito:`B`,explicacao:`Os quatro princípios clássicos da bioética são: autonomia, beneficência, não-maleficência e justiça.`},{id:`bioet-022`,topico:`principios_bioeticos`,banca:`USP`,ano:2022,dificuldade:`medio`,enunciado:`A aplicação do princípio da beneficência na medicina veterinária implica:`,alternativas:[`A) Realizar apenas procedimentos gratuitos`,`B) Agir sempre em benefício do paciente, promovendo seu bem-estar`,`C) Obedecer cegamente às instruções do proprietário`,`D) Priorizar o lucro sobre o tratamento`,`E) Evitar procedimentos de risco em qualquer situação`],gabarito:`B`,explicacao:`A beneficência exige que o profissional aja de forma a promover o bem-estar e os melhores interesses do paciente.`},{id:`bioet-023`,topico:`principios_bioeticos`,banca:`UFRRJ`,ano:2023,dificuldade:`medio`,enunciado:`Na aplicação prática do princípio da autonomia na veterinária, é correto afirmar que:`,alternativas:[`A) O animal é considerado totalmente autônomo em suas decisões`,`B) O proprietário exerce a autonomia em nome do animal, devendo ser devidamente informado`,`C) O médico veterinário não precisa respeitar a decisão do proprietário`,`D) A autonomia se aplica apenas em casos de eutanásia`,`E) O princípio da autonomia é incompatível com a prática veterinária`],gabarito:`B`,explicacao:`Como os animais não podem expressar autonomia diretamente, o proprietário/tutor exerce esse papel, desde que devidamente informado.`},{id:`bioet-024`,topico:`principios_bioeticos`,banca:`MAPA`,ano:2022,dificuldade:`dificil`,enunciado:`Analise as afirmativas sobre princípios bioéticos na veterinária:
I. O princípio da não-maleficência é absoluto e nunca pode ser violado.
II. O princípio da justiça pode exigir que recursos limitados sejam alocados de forma equitativa.
III. A beneficência e a não-maleficência são frequentemente complementares.
IV. O princípio da autonomia permite que o proprietário recuse tratamentos essenciais.
Está correto APENAS:`,alternativas:[`A) I e II`,`B) II e III`,`C) I, III e IV`,`D) II, III e IV`,`E) Todas`],gabarito:`D`,explicacao:`A afirmativa I é falsa pois princípios bioéticos podem entrar em conflito. As afirmativas II, III e IV são corretas.`},{id:`bioet-025`,topico:`principios_bioeticos`,banca:`ENAV`,ano:2022,dificuldade:`facil`,enunciado:`A expressão "primum non nocere" (primeiro, não causar dano) está associada a qual princípio bioético?`,alternativas:[`A) Autonomia`,`B) Beneficência`,`C) Não-maleficência`,`D) Justiça`,`E) Consentimento informado`],gabarito:`C`,explicacao:`Primum non nocere é o lema fundamental do princípio da não-maleficência, que orienta o profissional a não causar dano ao paciente.`},{id:`bioet-026`,topico:`principios_bioeticos`,banca:`CESPE`,ano:2023,dificuldade:`medio`,enunciado:`Sobre a aplicação dos princípios bioéticos em animais de produção, é correto afirmar:`,alternativas:[`A) Os princípios bioéticos não se aplicam a animais de produção`,`B) A justiça inclui considerar tanto o bem-estar animal quanto a sustentabilidade da produção`,`C) A autonomia do animal de produção deve ser respeitada`,`D) A não-maleficência não é aplicável em sistemas de produção`,`E) A beneficência não é relevante em contextos produtivos`],gabarito:`B`,explicacao:`Em animais de produção, o princípio da justiça envolve equilibrar o bem-estar animal com a viabilidade e sustentabilidade da produção.`},{id:`bioet-027`,topico:`etica_profissional`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`O Código de Ética do Médico Veterinário é aprovado pelo:`,alternativas:[`A) Ministério da Agricultura`,`B) Conselho Federal de Medicina Veterinária (CFMV)`,`C) Congresso Nacional`,`D) Ministério da Saúde`,`E) Conselho Regional de Medicina Veterinária`],gabarito:`B`,explicacao:`O Código de Ética Veterinária é aprovado e fiscalizado pelo CFMV, com aplicação descentralizada pelos CRMVs.`},{id:`bioet-028`,topico:`etica_profissional`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`De acordo com o Código de Ética Veterinária, é vedado ao médico veterinário:`,alternativas:[`A) Prestar socorro em caso de urgência`,`B) Emitir laudos e atestados baseados em exames clínicos`,`C) Atender animais de outro profissional sem autorização`,`D) Prescrever medicamentos de uso veterinário`,`E) Realizar procedimentos cirúrgicos quando necessário`],gabarito:`C`,explicacao:`É vedado ao médico veterinário atender animal sob cuidados de colega sem autorização expressa deste.`},{id:`bioet-029`,topico:`etica_profissional`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`A responsabilidade profissional do médico veterinário abrange:`,alternativas:[`A) Apenas a responsabilidade criminal`,`B) Responsabilidades civil, criminal e ético-disciplinar`,`C) Apenas a responsabilidade civil`,`D) Apenas a responsabilidade administrativa`,`E) Responsabilidade civil e patrimonial apenas`],gabarito:`B`,explicacao:`O médico veterinário pode responder civilmente, criminalmente e ético-disciplinarmente por seus atos profissionais.`},{id:`bioet-030`,topico:`etica_profissional`,banca:`VUNESP`,ano:2022,dificuldade:`facil`,enunciado:`O sigilo profissional na Medicina Veterinária é:`,alternativas:[`A) Uma sugestão não obrigatória`,`B) Uma obrigação ética prevista no Código de Ética`,`C) Aplicável apenas a animais de estimação`,`D) Exigido apenas em casos de doenças infectocontagiosas`,`E) Desnecessário na prática veterinária`],gabarito:`B`,explicacao:`O sigilo profissional é obrigação ética prevista no Código de Ética Veterinária, protegendo informações do proprietário e do paciente.`},{id:`bioet-031`,topico:`etica_profissional`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`Segundo o Código de Ética Veterinária, o médico veterinário deve:`,alternativas:[`A) Cobrar honorários acima do mercado para garantir qualidade`,`B) Manter atualização profissional e buscar aprimoramento contínuo`,`C) Atender apenas animais de grande porte`,`D) Recusar-se a atender em casos de emergência`,`E) Exercer atividades não previstas em sua formação`],gabarito:`B`,explicacao:`O profissional tem o dever de manter-se atualizado e buscar aprimoramento contínuo de seus conhecimentos.`},{id:`bioet-032`,topico:`etica_profissional`,banca:`CRMV`,ano:2022,dificuldade:`dificil`,enunciado:`A publicidade profissional do médico veterinário, conforme o Código de Ética, deve:`,alternativas:[`A) Ser proibida em qualquer circunstância`,`B) Ser veraz, discreta e não conter informações enganosas ou sensacionalistas`,`C) Incluir promessas de cura`,`D) Ser realizada apenas em redes sociais`,`E) Mencionar preços de concorrentes`],gabarito:`B`,explicacao:`A publicidade profissional é permitida desde que veraz, discreta, sem informações enganosas ou sensacionalistas.`},{id:`bioet-033`,topico:`etica_profissional`,banca:`UFMG`,ano:2023,dificuldade:`medio`,enunciado:`O exercício ilegal da Medicina Veterinária é:`,alternativas:[`A) Permitido para tratadores de animais experientes`,`B) Crime previsto em lei, passível de sanções penais e administrativas`,`C) Permitido em casos de emergência`,`D) Apenas uma infração administrativa leve`,`E) Permitido para médicos de outras especialidades`],gabarito:`B`,explicacao:`O exercício ilegal da profissão é crime previsto em lei e pode resultar em sanções penais e administrativas.`},{id:`bioet-034`,topico:`etica_profissional`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A inscrição no Conselho Regional de Medicina Veterinária (CRMV) é:`,alternativas:[`A) Facultativa para o exercício da profissão`,`B) Obrigatória para o exercício legal da Medicina Veterinária`,`C) Necessária apenas para quem atende animais silvestres`,`D) Exigida apenas para concursos públicos`,`E) Obrigatória apenas para quem trabalha em indústria`],gabarito:`B`,explicacao:`A inscrição no CRMV é obrigatória para o exercício legal da Medicina Veterinária em todo o território nacional.`},{id:`bioet-035`,topico:`etica_profissional`,banca:`USP`,ano:2023,dificuldade:`dificil`,enunciado:`No Código de Ética Veterinária, a relação entre médicos veterinários deve pautar-se por:`,alternativas:[`A) Competição agressiva por mercado`,`B) Respeito mútuo, coleguismo e lealdade profissional`,`C) Indiferença entre colegas`,`D) Compartilhamento obrigatório de prontuários`,`E) Subordinação hierárquica rígida`],gabarito:`B`,explicacao:`O Código de Ética prega o respeito mútuo, o coleguismo e a lealdade na relação entre profissionais.`},{id:`bioet-036`,topico:`etica_profissional`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`Sobre os deveres do médico veterinário para com a sociedade, é correto afirmar:`,alternativas:[`A) O profissional deve priorizar exclusivamente seus interesses financeiros`,`B) Deve contribuir para a saúde pública, vigilância sanitária e proteção ambiental`,`C) Não tem responsabilidade com a saúde pública`,`D) Deve atender apenas quem pode pagar`,`E) Não é obrigado a notificar doenças de notificação compulsória`],gabarito:`B`,explicacao:`O médico veterinário tem deveres para com a sociedade, incluindo participação em ações de saúde pública e vigilância sanitária.`},{id:`bioet-037`,topico:`etica_profissional`,banca:`MAPA`,ano:2023,dificuldade:`medio`,enunciado:`A reserva profissional do médico veterinário abrange:`,alternativas:[`A) Apenas atos cirúrgicos`,`B) Atos privativos definidos pela legislação, incluindo diagnóstico, prescrição e cirurgia`,`C) Qualquer ato relacionado a animais`,`D) Apenas vacinações e medicações`,`E) Apenas laudos técnicos`],gabarito:`B`,explicacao:`A reserva profissional inclui diagnóstico, prescrição de medicamentos, atos cirúrgicos e outros definidos em lei.`},{id:`bioet-038`,topico:`etica_profissional`,banca:`ENAV`,ano:2022,dificuldade:`dificil`,enunciado:`Segundo a Lei 5.517/1968, que regulamenta o exercício da Medicina Veterinária, o médico veterinário:`,alternativas:[`A) Pode delegar qualquer ato a auxiliares`,`B) Deve supervisionar os atos delegados a auxiliares e é responsável por eles`,`C) Não pode delegar nenhuma atividade`,`D) Só pode delegar atos em hospitais públicos`,`E) Não responde por atos de auxiliares`],gabarito:`B`,explicacao:`O médico veterinário pode delegar atividades a auxiliares, mas mantém a responsabilidade pela supervisão e pelos resultados.`},{id:`bioet-039`,topico:`etica_profissional`,banca:`CESPE`,ano:2023,dificuldade:`facil`,enunciado:`O médico veterinário que testemunha um colega cometendo infração ética deve:`,alternativas:[`A) Ignorar a situação`,`B) Denunciar ao CRMV competente`,`C) Resolver o caso diretamente com o colega`,`D) Publicar nas redes sociais`,`E) Apenas afastar-se do colega`],gabarito:`B`,explicacao:`O profissional tem o dever ético de comunicar infrações ao CRMV competente para apuração.`},{id:`bioet-040`,topico:`experimentacao_animal`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`Os princípios dos 3Rs na experimentação animal referem-se a:`,alternativas:[`A) Reproduzir, Reutilizar, Reciclar`,`B) Redução, Refinamento, Substituição`,`C) Replicar, Refinar, Reproduzir`,`D) Reduzir, Replicar, Relatar`,`E) Reprodução, Refinamento, Substituição`],gabarito:`B`,explicacao:`Os 3Rs são: Redução (do número de animais), Refinamento (das técnicas) e Substituição (por métodos alternativos).`},{id:`bioet-041`,topico:`experimentacao_animal`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`A CEUA (Comissão de Ética no Uso de Animais) é responsável por:`,alternativas:[`A) Financiar pesquisas com animais`,`B) Acompanhar e avaliar procedimentos éticos em pesquisas que utilizam animais`,`C) Substituir o uso de animais em pesquisa`,`D) Fornecer animais para laboratórios`,`E) Regular o mercado de animais de estimação`],gabarito:`B`,explicacao:`A CEUA é responsável pela avaliação e acompanhamento ético de projetos de pesquisa que envolvem animais.`},{id:`bioet-042`,topico:`experimentacao_animal`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`A Lei Arouca (Lei 11.794/2008) que regulamenta o uso de animais em pesquisa:`,alternativas:[`A) Proíbe totalmente o uso de animais em pesquisa`,`B) Regulamenta o uso de animais em ensino e pesquisa, criando o CONCEA`,`C) Permite o uso sem restrições de qualquer animal`,`D) Aplica-se apenas a primatas`,`E) Não prevê sanções por descumprimento`],gabarito:`B`,explicacao:`A Lei 11.794/2008 regulamenta o uso de animais em ensino e pesquisa científica e cria o CONCEA (Conselho Nacional de Controle de Experimentação Animal).`},{id:`bioet-043`,topico:`experimentacao_animal`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`Sobre o princípio da Substituição nos 3Rs, é correto afirmar que:`,alternativas:[`A) Deve-se substituir animais por outros sempre que possível`,`B) Deve-se utilizar métodos alternativos que evitem ou reduzam o uso de animais conscientes`,`C) A substituição é obrigatória em todos os casos`,`D) Apenas invertebrados podem ser substituídos`,`E) O uso de simuladores é proibido por lei`],gabarito:`B`,explicacao:`A Substituição visa utilizar métodos alternativos que substituam, sempre que possível, o uso de animais conscientes em experimentação.`},{id:`bioet-044`,topico:`experimentacao_animal`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`O CONCEA (Conselho Nacional de Controle de Experimentação Animal) é:`,alternativas:[`A) Uma ONG internacional`,`B) Órgão colegiado vinculado ao MCTI, responsável por regulamentar e fiscalizar a experimentação animal`,`C) Um conselho profissional de veterinários`,`D) Uma comissão da OMS`,`E) Um departamento universitário`],gabarito:`B`,explicacao:`O CONCEA é órgão colegiado do Ministério da Ciência, Tecnologia e Inovações, responsável pela regulamentação e controle da experimentação animal.`},{id:`bioet-045`,topico:`experimentacao_animal`,banca:`CRMV`,ano:2022,dificuldade:`facil`,enunciado:`O princípio do Refinamento na experimentação animal refere-se a:`,alternativas:[`A) Reduzir o número de animais utilizados`,`B) Aprimorar os procedimentos para minimizar dor e sofrimento`,`C) Substituir animais por modelos computacionais`,`D) Aumentar o número de repetições experimentais`,`E) Utilizar apenas animais geneticamente modificados`],gabarito:`B`,explicacao:`O Refinamento busca aprimorar técnicas e procedimentos para minimizar dor, sofrimento e angústia dos animais.`},{id:`bioet-046`,topico:`experimentacao_animal`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`Em um projeto de pesquisa que utiliza animais, a anestesia e a analgesia pós-operatória são:`,alternativas:[`A) Recomendadas apenas quando o pesquisador julgar necessário`,`B) Obrigatórias, salvo quando a própria natureza da pesquisa impedir, devendo ser justificada`,`C) Proibidas por comprometerem os resultados`,`D) Obrigatórias apenas para mamíferos`,`E) Desnecessárias em procedimentos minimamente invasivos`],gabarito:`B`,explicacao:`A Lei Arouca e resoluções do CONCEA exigem anestesia/analgesia, exceto quando a natureza da pesquisa impossibilitar, devendo haver justificativa.`},{id:`bioet-047`,topico:`experimentacao_animal`,banca:`UNESP`,ano:2022,dificuldade:`medio`,enunciado:`O princípio da Redução nos 3Rs significa:`,alternativas:[`A) Eliminar completamente o uso de animais`,`B) Reduzir o número de animais ao mínimo necessário para obtenção de resultados válidos`,`C) Utilizar animais menores em vez de grandes`,`D) Reduzir o tempo de experimentação`,`E) Reduzir o custo da pesquisa`],gabarito:`B`,explicacao:`A Redução visa diminuir o número de animais utilizados ao mínimo necessário para obtenção de informações científicas válidas.`},{id:`bioet-048`,topico:`experimentacao_animal`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`Em pesquisas com animais, a avaliação de bem-estar deve incluir:`,alternativas:[`A) Apenas indicadores fisiológicos`,`B) Indicadores fisiológicos, comportamentais e clínicos`,`C) Apenas a observação visual do animal`,`D) Apenas o peso corporal`,`E) Apenas relatórios do pesquisador`],gabarito:`B`,explicacao:`A avaliação de bem-estar deve ser multidimensional, incluindo indicadores fisiológicos, comportamentais e clínicos.`},{id:`bioet-049`,topico:`experimentacao_animal`,banca:`UFRRJ`,ano:2022,dificuldade:`dificil`,enunciado:`Sobre o uso de animais em testes de cosméticos no Brasil:`,alternativas:[`A) É livre e não há regulamentação`,`B) A Lei 14.515/2022 proíbe testes de cosméticos em animais no Brasil`,`C) É permitido apenas para produtos importados`,`D) Não há legislação específica`,`E) É permitido apenas em casos de risco à saúde`],gabarito:`B`,explicacao:`A Lei 14.515/2022 proíbe testes de toxicidade e segurança de produtos cosméticos em animais no Brasil.`},{id:`bioet-050`,topico:`experimentacao_animal`,banca:`MAPA`,ano:2023,dificuldade:`medio`,enunciado:`A EUBAM (Estratégia Universitária Brasileira de Métodos Alternativos) tem como objetivo:`,alternativas:[`A) Proibir toda pesquisa com animais`,`B) Promover o desenvolvimento e uso de métodos alternativos à experimentação animal`,`C) Financiar laboratórios de pesquisa`,`D) Regular o comércio de animais de laboratório`,`E) Formar veterinários especializados`],gabarito:`B`,explicacao:`A EUBAM visa promover e facilitar o desenvolvimento e uso de métodos alternativos ao uso de animais.`},{id:`bioet-051`,topico:`experimentacao_animal`,banca:`ENAV`,ano:2022,dificuldade:`facil`,enunciado:`As normas do CONCEA para uso de animais em ensino e pesquisa aplicam-se:`,alternativas:[`A) Apenas a instituições públicas`,`B) A todas as instituições científicas e educacionais que utilizam animais`,`C) Apenas a universidades federais`,`D) Apenas a laboratórios farmacêuticos`,`E) Apenas a centros de pesquisa privados`],gabarito:`B`,explicacao:`As normas do CONCEA aplicam-se a todas as instituições que criam ou utilizam animais em ensino e pesquisa.`},{id:`bioet-052`,topico:`experimentacao_animal`,banca:`CESPE`,ano:2023,dificuldade:`dificil`,enunciado:`Em um projeto de pesquisa, a utilização de animal geneticamente modificado (OGM animal) exige:`,alternativas:[`A) Apenas aprovação do orientador`,`B) Aprovação da CEUA e cumprimento das normas do CONCEA e da CTNBio`,`C) Apenas autorização do proprietário do animal`,`D) Não há exigências adicionais`,`E) Apenas relatório final à FAPESP`],gabarito:`B`,explicacao:`O uso de animais geneticamente modificados requer aprovação da CEUA e conformidade com normas do CONCEA e da CTNBio.`},{id:`bioet-053`,topico:`eutanasia`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`A eutanásia animal, em sentido etimológico, significa:`,alternativas:[`A) Morte dolorosa`,`B) Boa morte, morte sem sofrimento`,`C) Morte natural`,`D) Morte acidental`,`E) Morte assistida por equipamentos`],gabarito:`B`,explicacao:`Eutanásia vem do grego "eu" (boa) e "thanatos" (morte), significando morte sem sofrimento.`},{id:`bioet-054`,topico:`eutanasia`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`As indicações éticas para eutanásia animal incluem:`,alternativas:[`A) Apenas doenças incuráveis`,`B) Doenças terminais com sofrimento, lesões irreversíveis graves e comportamento perigoso irremediável`,`C) Qualquer doença que demande tratamento prolongado`,`D) Apenas quando o proprietário solicita`,`E) Apenas para animais de grande porte`],gabarito:`B`,explicacao:`A eutanásia é eticamente indicada em casos de sofrimento sem possibilidade de recuperação, lesões graves irreversíveis e comportamento irremediavelmente perigoso.`},{id:`bioet-055`,topico:`eutanasia`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`O método de eutanásia considerado mais indicado para cães e gatos em ambiente clínico é:`,alternativas:[`A) Deslocamento cervical`,`B) Sobredose de barbitúrico intravenoso`,`C) Exposição ao frio`,`D) Afogamento`,`E) Decapitação`],gabarito:`B`,explicacao:`A sobredose de barbitúrico (pentobarbital) por via intravenosa é o método mais recomendado por ser rápido e indolor.`},{id:`bioet-056`,topico:`eutanasia`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`Sobre a eutanásia por conveniência (quando o animal não apresenta doença grave), é correto afirmar:`,alternativas:[`A) É sempre proibida pelo Código de Ética`,`B) Deve ser evitada, mas o profissional pode realizá-la em casos específicos após tentativas de adoção ou encaminhamento`,`C) É livre e não há restrições`,`D) Só pode ser realizada em abrigos de animais`,`E) É permitida apenas para animais selvagens`],gabarito:`B`,explicacao:`A eutanásia por conveniência deve ser evitada; o profissional deve buscar alternativas como adoção, mas pode realizá-la em situações específicas.`},{id:`bioet-057`,topico:`eutanasia`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`Antes de realizar a eutanásia, o médico veterinário deve:`,alternativas:[`A) Apenas verificar o estado do animal`,`B) Informar o proprietário sobre o procedimento, obter consentimento e garantir que não há alternativas viáveis`,`C) Realizar o procedimento imediatamente`,`D) Consultar apenas o código de ética`,`E) Não é necessário informar o proprietário`],gabarito:`B`,explicacao:`O profissional deve informar adequadamente o proprietário, obter consentimento e certificar-se de que não há alternativas terapêuticas viáveis.`},{id:`bioet-058`,topico:`eutanasia`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`A Resolução CFMV 1093/2014 que trata de eutanásia animal estabelece que:`,alternativas:[`A) A eutanásia é proibida em qualquer circunstância`,`B) A eutanásia deve ser realizada apenas quando todos os recursos terapêuticos forem esgotados ou quando houver sofrimento injustificável`,`C) Qualquer pessoa pode solicitar a eutanásia`,`D) A eutanásia só pode ser realizada em clínicas particulares`,`E) Não há regulamentação específica para eutanásia animal`],gabarito:`B`,explicacao:`A resolução estabelece que a eutanásia deve ser considerada apenas quando recursos terapêuticos forem esgotados ou quando houver sofrimento injustificável.`},{id:`bioet-059`,topico:`eutanasia`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`Os métodos de eutanásia considerados inaceitáveis pela AVMA (American Veterinary Medical Association) incluem:`,alternativas:[`A) Sobredose de barbitúricos`,`B) Afogamento, uso de venenos domésticos e métodos que causem sofrimento desnecessário`,`C) Injeção intravenosa de cloreto de potássio`,`D) Disparo de arma de fogo em situações específicas`,`E) Exposição a gases inertes`],gabarito:`B`,explicacao:`A AVMA considera inaceitáveis métodos que causem sofrimento desnecessário, como afogamento, venenos domésticos e outros.`},{id:`bioet-060`,topico:`eutanasia`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A eutanásia de animais em abrigos superlotados é considerada:`,alternativas:[`A) Crime ambiental`,`B) Eutanásia por conveniência, que deve ser evitada mediante políticas de controle populacional e adoção`,`C) Prática recomendada pela OMS`,`D) Proibida em todo o território nacional`,`E) Obrigatória por lei municipal`],gabarito:`B`,explicacao:`A eutanásia em abrigos é considerada eutanásia por conveniência e deve ser evitada, priorizando-se controle populacional e adoção.`},{id:`bioet-061`,topico:`eutanasia`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`Sobre a eutanásia de animais de produção em frigoríficos, é correto afirmar:`,alternativas:[`A) Não existe regulamentação específica`,`B) Deve seguir normas do MAPA que garantam o bem-estar animal durante o abate humanitário`,`C) A eutanásia é proibida em frigoríficos`,`D) Não há necessidade de insensibilização pré-abate`,`E) O MAPA não fiscaliza o processo`],gabarito:`B`,explicacao:`O MAPA regulamenta o abate humanitário, exigindo insensibilização prévia para garantir o bem-estar dos animais.`},{id:`bioet-062`,topico:`eutanasia`,banca:`UFRRJ`,ano:2022,dificuldade:`dificil`,enunciado:`A aplicação de eutanásia em animal agressivo que representa risco à segurança pública é:`,alternativas:[`A) Proibida em qualquer circunstância`,`B) Permitida após esgotadas as alternativas de manejo e condicionamento, com registro documental`,`C) Permitida sem necessidade de justificativa`,`D) De responsabilidade exclusiva do proprietário`,`E) Permitida apenas por ordem judicial`],gabarito:`B`,explicacao:`A eutanásia por agressividade é permitida quando esgotadas as alternativas, devendo haver registro documental.`},{id:`bioet-063`,topico:`eutanasia`,banca:`MAPA`,ano:2023,dificuldade:`medio`,enunciado:`O conceito de "abate humanitário" refere-se a:`,alternativas:[`A) Abate sem insensibilização prévia`,`B) Processo que minimiza dor e sofrimento, com insensibilização antes do abate`,`C) Abate apenas de animais doentes`,`D) Eutanásia de animais de estimação`,`E) Abate de animais para consumo religioso`],gabarito:`B`,explicacao:`O abate humanitário é o processo que visa minimizar dor e sofrimento, com insensibilização adequada antes do abate.`},{id:`bioet-064`,topico:`eutanasia`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`A solicitação de eutanásia por parte de um terceiro que não o proprietário do animal:`,alternativas:[`A) É sempre aceitável`,`B) Deve ser avaliada com cautela, verificando a legitimidade do solicitante`,`C) É proibida em qualquer caso`,`D) Só é aceita em casos de animais selvagens`,`E) Não é regulamentada`],gabarito:`B`,explicacao:`O profissional deve verificar a legitimidade de quem solicita a eutanásia, garantindo que há autoridade para tal.`},{id:`bioet-065`,topico:`eutanasia`,banca:`CESPE`,ano:2023,dificuldade:`dificil`,enunciado:`Sobre o manejo do corpo após a eutanásia, o profissional deve:`,alternativas:[`A) Descartar em lixo comum`,`B) Seguir a legislação ambiental e sanitária vigente para destinação adequada`,`C) Enterrar em qualquer terreno`,`D) Não há regulamentação específica`,`E) Cremar sem autorização ambiental`],gabarito:`B`,explicacao:`A destinação do corpo deve seguir a legislação ambiental e sanitária, respeitando normas de descarte e destinação.`},{id:`bioet-066`,topico:`consentimento_informado`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`O consentimento informado na Medicina Veterinária é:`,alternativas:[`A) Obrigatório apenas para cirurgias eletivas`,`B) O processo pelo qual o proprietário autoriza procedimentos após receber informações adequadas`,`C) Desnecessário quando o animal está em risco de vida`,`D) Exigido apenas em hospitais veterinários públicos`,`E) Um documento que o proprietário assina sem necessidade de explicação`],gabarito:`B`,explicacao:`O consentimento informado é o processo contínuo de comunicação que permite ao proprietário decidir de forma consciente.`},{id:`bioet-067`,topico:`consentimento_informado`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`Para que o consentimento informado seja válido, é necessário que:`,alternativas:[`A) O proprietário apenas assine o documento`,`B) As informações sejam compreensíveis, haja capacidade de decidir e a decisão seja voluntária`,`C) Apenas o médico veterinário considere adequado`,`D) O proprietário seja maior de 21 anos`,`E) Haja testemunha presente`],gabarito:`B`,explicacao:`O consentimento informado válido exige informações compreensíveis, capacidade de decisão e voluntariedade.`},{id:`bioet-068`,topico:`consentimento_informado`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`Em uma emergência veterinária onde o proprietário não pode ser contactado:`,alternativas:[`A) O profissional deve aguardar o contato para qualquer procedimento`,`B) O profissional pode realizar procedimentos necessários para salvar a vida do animal, documentando as ações`,`C) O consentimento é dispensável em qualquer caso`,`D) Deve-se contactar a polícia antes de qualquer atendimento`,`E) O animal deve ser encaminhado a outro serviço`],gabarito:`B`,explicacao:`Em emergências, o profissional pode agir para preservar a vida do animal, devendo documentar todas as ações realizadas.`},{id:`bioet-069`,topico:`consentimento_informado`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`A recusa do proprietário em autorizar um procedimento que o profissional considera necessário para o bem-estar do animal:`,alternativas:[`A) Deve ser ignorada pelo profissional`,`B) Deve ser respeitada, mas o profissional deve documentar a orientação e a recusa`,`C) Obriga o profissional a realizar o procedimento contra a vontade`,`D) Gera responsabilidade criminal para o proprietário`,`E) Permite que o profissional acione a polícia imediatamente`],gabarito:`B`,explicacao:`O profissional deve respeitar a autonomia do proprietário, mas documentar que orientou adequadamente e houve recusa.`},{id:`bioet-070`,topico:`consentimento_informado`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`As informações que devem ser fornecidas ao proprietário no consentimento informado incluem:`,alternativas:[`A) Apenas o diagnóstico`,`B) Diagnóstico, opções de tratamento, riscos, benefícios e custos`,`C) Apenas o custo do tratamento`,`D) Apenas os riscos do procedimento`,`E) Apenas o prognóstico`],gabarito:`B`,explicacao:`O consentimento informado deve incluir diagnóstico, alternativas terapêuticas, riscos, benefícios e custos.`},{id:`bioet-071`,topico:`consentimento_informado`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`O termo de consentimento informado na veterinária:`,alternativas:[`A) Deve ser padronizado para todos os procedimentos`,`B) Deve ser individualizado, adaptado ao caso específico e linguagem acessível ao proprietário`,`C) Pode ser substituído por consentimento verbal em todos os casos`,`D) É exigido apenas em hospitais públicos`,`E) Não tem validade legal`],gabarito:`B`,explicacao:`O termo deve ser individualizado, com linguagem clara e acessível, adaptado à situação específica de cada paciente.`},{id:`bioet-072`,topico:`consentimento_informado`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`O conceito de consentimento informado contínuo na veterinária significa que:`,alternativas:[`A) O consentimento dado uma vez é válido para todo o tratamento`,`B) O proprietário deve ser informado continuamente sobre a evolução do caso e novas decisões`,`C) O consentimento é necessário apenas no início do tratamento`,`D) O profissional não precisa atualizar o proprietário sobre mudanças`,`E) O consentimento contínuo é opcional`],gabarito:`B`,explicacao:`O consentimento é um processo contínuo: o proprietário deve ser informado sobre evoluções e novas decisões durante todo o tratamento.`},{id:`bioet-073`,topico:`consentimento_informado`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A capacidade de consentir na veterinária refere-se:`,alternativas:[`A) À capacidade do animal de expressar consentimento`,`B) À capacidade do proprietário/tutor de compreender as informações e tomar decisões`,`C) À capacidade financeira do proprietário`,`D) À idade mínima do proprietário para assinar documentos`,`E) À formação acadêmica do proprietário`],gabarito:`B`,explicacao:`A capacidade de consentir refere-se à habilidade do proprietário/tutor de compreender informações e tomar decisões.`},{id:`bioet-074`,topico:`consentimento_informado`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`Em caso de divergência entre proprietários sobre o tratamento de um animal:`,alternativas:[`A) O médico veterinário deve decidir`,`B) Deve-se buscar resolução consensual, e em caso de impasse, priorizar o tratamento que beneficie o animal`,`C) O animal deve ser transferido para outro profissional`,`D) O tratamento deve ser suspenso até resolução`,`E) Não há orientação específica`],gabarito:`B`,explicacao:`O profissional deve mediar a divergência, buscando consenso e priorizando o bem-estar do animal.`},{id:`bioet-075`,topico:`consentimento_informado`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`A documentação do consentimento informado é importante porque:`,alternativas:[`A) Apenas para fins acadêmicos`,`B) Serve como prova de que o profissional informou adequadamente e o proprietário consentiu`,`C) Não tem valor jurídico`,`D) É exigida apenas em cirurgias estéticas`,`E) É opcional na prática veterinária`],gabarito:`B`,explicacao:`A documentação serve como proteção legal para o profissional e como prova de que houve informação adequada.`},{id:`bioet-076`,topico:`consentimento_informado`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`Sobre o consentimento informado em procedimentos experimentais com animais:`,alternativas:[`A) Não é necessário`,`B) O proprietário deve consentir, e o projeto deve ser aprovado pela CEUA`,`C) Apenas a aprovação da CEUA é suficiente`,`D) O consentimento do animal é necessário`,`E) É necessário apenas para animais de companhia`],gabarito:`B`,explicacao:`Procedimentos experimentais exigem tanto o consentimento do proprietário quanto a aprovação ética da CEUA.`},{id:`bioet-077`,topico:`consentimento_informado`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`Quando o proprietário não entende a língua portuguesa fluentemente, o consentimento informado:`,alternativas:[`A) Pode ser dispensado`,`B) Deve ser obtido com auxílio de intérprete ou em língua compreendida pelo proprietário`,`C) Pode ser substituído por gestos`,`D) Não é necessário se houver familiar presente`,`E) Deve ser apenas verbal`],gabarito:`B`,explicacao:`O profissional deve garantir que o proprietário compreenda plenamente as informações, utilizando intérprete se necessário.`},{id:`bioet-078`,topico:`consentimento_informado`,banca:`CESPE`,ano:2023,dificuldade:`facil`,enunciado:`O consentimento informado é uma extensão de qual princípio bioético?`,alternativas:[`A) Beneficência`,`B) Não-maleficência`,`C) Autonomia`,`D) Justiça`,`E) Sigilo`],gabarito:`C`,explicacao:`O consentimento informado é a expressão prática do princípio da autonomia, garantindo que decisões sejam tomadas de forma livre e informada.`},{id:`bioet-079`,topico:`conflitos_eticos`,banca:`ENAV`,ano:2023,dificuldade:`medio`,enunciado:`Um conflito ético comum na prática veterinária ocorre quando:`,alternativas:[`A) O animal coopera com o tratamento`,`B) O proprietário deseja prolongar a vida do animal em sofrimento sem possibilidade de cura`,`C) O profissional está atualizado`,`D) O tratamento é simples e de baixo custo`,`E) O animal é jovem e saudável`],gabarito:`B`,explicacao:`O conflito surge quando o desejo do proprietário de prolongar a vida entra em conflito com o princípio de não-maleficência em relação ao animal.`},{id:`bioet-080`,topico:`conflitos_eticos`,banca:`CESPE`,ano:2022,dificuldade:`dificil`,enunciado:`O termo "eutanasia por conveniência" refere-se a:`,alternativas:[`A) Eutanásia de animal terminal`,`B) Eutanásia realizada por motivos de conveniência do proprietário, sem sofrimento animal significativo`,`C) Eutanásia em caso de zoonose`,`D) Eutanásia de animal agressivo`,`E) Eutanásia de emergência`],gabarito:`B`,explicacao:`A eutanásia por conveniência é aquela realizada por motivos de comodidade do proprietário, sem que o animal apresente sofrimento grave.`},{id:`bioet-081`,topico:`conflitos_eticos`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`Quando o tratamento recomendado pelo veterinário é recusado pelo proprietário por motivos financeiros:`,alternativas:[`A) O profissional deve realizar o tratamento sem cobrar`,`B) O profissional deve apresentar alternativas viáveis e documentar a orientação`,`C) O profissional deve ignorar a recusa`,`D) O profissional deve denunciar o proprietário`,`E) Não há conflito ético nessa situação`],gabarito:`B`,explicacao:`O profissional deve buscar alternativas acessíveis, informar sobre consequências da recusa e documentar.`},{id:`bioet-082`,topico:`conflitos_eticos`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`Em situações de conflito entre o bem-estar animal e interesses econômicos do proprietário (ex: animal de produção), o profissional deve:`,alternativas:[`A) Priorizar sempre os interesses econômicos`,`B) Buscar equilíbrio entre o bem-estar animal e a viabilidade econômica, dentro dos limites éticos`,`C) Recusar-se a atender animais de produção`,`D) Ignorar o bem-estar animal`,`E) Denunciar o proprietário sempre`],gabarito:`B`,explicacao:`O profissional deve buscar equilíbrio ético entre o bem-estar animal e a viabilidade econômica, sem violar princípios fundamentais.`},{id:`bioet-083`,topico:`conflitos_eticos`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`O conflito de interesse na prática veterinária pode ocorrer quando:`,alternativas:[`A) O profissional atende apenas uma espécie`,`B) O interesse financeiro do profissional influencia a recomendação de tratamento`,`C) O profissional trabalha em clínica própria`,`D) O profissional recusa atendimento`,`E) O profissional atualiza seus conhecimentos`],gabarito:`B`,explicacao:`O conflito de interesse ocorre quando fatores externos, como financeiros, influenciam decisões que deveriam ser baseadas apenas no interesse do paciente.`},{id:`bioet-084`,topico:`conflitos_eticos`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`Em caso de suspeita de maus-tratos por parte do proprietário, o médico veterinário deve:`,alternativas:[`A) Ignorar a suspeita`,`B) Comunicar às autoridades competentes e documentar as evidências`,`C) Tratar o animal e não comunicar`,`D) Confrontar o proprietário diretamente`,`E) Recusar o atendimento`],gabarito:`B`,explicacao:`O profissional tem o dever ético e legal de comunicar suspeitas de maus-tratos às autoridades competentes.`},{id:`bioet-085`,topico:`conflitos_eticos`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`O conceito de "dilema do duplo efeito" na veterinária ocorre quando:`,alternativas:[`A) O tratamento tem apenas efeitos positivos`,`B) Uma ação tem tanto efeito positivo (alívio da dor) quanto negativo (possível encurtamento da vida)`,`C) O proprietário deseja dois tratamentos diferentes`,`D) O profissional trabalha em dois empregos`,`E) O animal tem duas doenças simultâneas`],gabarito:`B`,explicacao:`O dilema do duplo efeito ocorre quando uma ação terapêutica visa aliviar o sofrimento, mas pode ter efeito colateral indesejado.`},{id:`bioet-086`,topico:`conflitos_eticos`,banca:`UNESP`,ano:2022,dificuldade:`medio`,enunciado:`A objeção de consciência do médico veterinário permite que ele:`,alternativas:[`A) Recuse qualquer atendimento`,`B) Recuse realizar procedimentos que firam seus princípios éticos, desde que encaminhe o caso adequadamente`,`C) Imponha suas crenças ao proprietário`,`D) Não atenda emergências`,`E) Ignore o Código de Ética`],gabarito:`B`,explicacao:`O profissional pode exercer objeção de consciência, mas deve encaminhar o caso a outro profissional para não prejudicar o animal.`},{id:`bioet-087`,topico:`conflitos_eticos`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`Em situações de desastres naturais com múltiplos animais feridos e recursos limitados, o critério ético de triagem deve considerar:`,alternativas:[`A) Apenas a espécie do animal`,`B) A gravidade do estado, probabilidade de sobrevida e disponibilidade de recursos`,`C) Apenas o valor econômico do animal`,`D) A ordem de chegada sem exceção`,`E) Apenas animais de estimação`],gabarito:`B`,explicacao:`A triagem ética em desastres deve considerar gravidade, prognóstico e disponibilidade de recursos para maximizar o benefício.`},{id:`bioet-088`,topico:`conflitos_eticos`,banca:`UFRRJ`,ano:2022,dificuldade:`dificil`,enunciado:`Quando dois proprietários coabitantes discordam sobre a eutanásia de um animal:`,alternativas:[`A) O profissional deve realizar a eutanásia se um consentir`,`B) O profissional deve buscar consenso e, em caso de impasse, priorizar o bem-estar do animal`,`C) O profissional deve recusar-se a atender`,`D) Deve-se aguardar decisão judicial`,`E) O profissional deve escolher o proprietário que oferece maior remuneração`],gabarito:`B`,explicacao:`O profissional deve mediar o conflito, buscando consenso e priorizando o bem-estar do animal.`},{id:`bioet-089`,topico:`conflitos_eticos`,banca:`MAPA`,ano:2023,dificuldade:`medio`,enunciado:`A utilização de animais em espetáculos circenses é um conflito ético que envolve:`,alternativas:[`A) Apenas questões de diversão`,`B) Bem-estar animal, direitos dos animais e regulamentação de uso de animais em entretenimento`,`C) Apenas questões financeiras`,`D) Nenhuma questão ética`,`E) Apenas questões de tradição cultural`],gabarito:`B`,explicacao:`O uso de animais em circos envolve questões de bem-estar, direitos animais e regulamentação específica.`},{id:`bioet-090`,topico:`conflitos_eticos`,banca:`ENAV`,ano:2022,dificuldade:`facil`,enunciado:`O profissional que se depara com um conflito ético deve:`,alternativas:[`A) Ignorar o conflito`,`B) Analisar a situação considerando princípios bioéticos, código de ética e legislação vigente`,`C) Seguir apenas sua intuição`,`D) Consultar apenas o proprietário`,`E) Realizar o procedimento mais lucrativo`],gabarito:`B`,explicacao:`O profissional deve fundamentar sua decisão em princípios bioéticos, no código de ética e na legislação.`},{id:`bioet-091`,topico:`conflitos_eticos`,banca:`CESPE`,ano:2023,dificuldade:`medio`,enunciado:`O uso de animais em testes de laboratório cosmético representa um conflito entre:`,alternativas:[`A) Apenas questões financeiras`,`B) Interesses industriais e o bem-estar dos animais utilizados nos testes`,`C) Questões de saúde pública apenas`,`D) Interesses acadêmicos apenas`,`E) Nenhum conflito relevante`],gabarito:`B`,explicacao:`Há conflito entre o interesse industrial em testar produtos e o bem-estar dos animais submetidos a testes.`},{id:`bioet-092`,topico:`responsabilidade_civil`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`A negligência na Medicina Veterinária é definida como:`,alternativas:[`A) Ação intencional de causar dano`,`B) Omissão ou falta de cuidado no exercício profissional`,`C) Falta de conhecimento técnico`,`D) Excesso de cautela no atendimento`,`E) Ação correta mas com resultado adverso`],gabarito:`B`,explicacao:`Negligência é a omissão ou falta de cuidado/atenção que o profissional deveria ter em determinada situação.`},{id:`bioet-093`,topico:`responsabilidade_civil`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`A imperícia profissional refere-se a:`,alternativas:[`A) Falta de cuidado em um procedimento conhecido`,`B) Falta de conhecimento técnico ou habilidade para realizar determinado procedimento`,`C) Ação deliberada de causar dano`,`D) Excesso de confiança no resultado`,`E) Omissão de socorro`],gabarito:`B`,explicacao:`Imperícia é a falta de conhecimento técnico ou habilidade necessária para a realização de determinada atividade profissional.`},{id:`bioet-094`,topico:`responsabilidade_civil`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`A imprudência na veterinária é caracterizada por:`,alternativas:[`A) Omissão de cuidados necessários`,`B) Ação temerária, sem as cautelas devidas, assumindo riscos desnecessários`,`C) Falta de habilidade técnica`,`D) Seguir protocolos estabelecidos`,`E) Recusar um atendimento`],gabarito:`B`,explicacao:`Imprudência é a ação de forma temerária, sem as cautelas devidas, assumindo riscos desnecessários.`},{id:`bioet-095`,topico:`responsabilidade_civil`,banca:`VUNESP`,ano:2022,dificuldade:`medio`,enunciado:`A responsabilidade civil do médico veterinário pode ser:`,alternativas:[`A) Apenas subjetiva`,`B) Objetiva ou subjetiva, dependendo da situação e do dano causado`,`C) Apenas objetiva`,`D) Inexistente na legislação brasileira`,`E) Apenas contratual`],gabarito:`B`,explicacao:`A responsabilidade civil pode ser objetiva (baseada no risco da atividade) ou subjetiva (baseada na culpa do profissional).`},{id:`bioet-096`,topico:`responsabilidade_civil`,banca:`AVAMEC`,ano:2023,dificuldade:`dificil`,enunciado:`O médico veterinário que realiza um procedimento para o qual não tem formação adequada comete:`,alternativas:[`A) Apenas infração administrativa`,`B) Imperícia, podendo gerar responsabilidade civil, criminal e ético-disciplinar`,`C) Apenas falta ética leve`,`D) Nenhuma infração se o resultado for satisfatório`,`E) Apenas responsabilidade contratual`],gabarito:`B`,explicacao:`A imperícia configura falta grave, gerando responsabilidade em múltiplas esferas (civil, criminal e ético-disciplinar).`},{id:`bioet-097`,topico:`responsabilidade_civil`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`O prontuário médico veterinário é importante para a responsabilidade civil porque:`,alternativas:[`A) É apenas um requisito burocrático`,`B) Documenta o atendimento, servindo como meio de prova em caso de litígio`,`C) Não tem valor jurídico`,`D) Serve apenas para controle financeiro`,`E) É opcional na prática veterinária`],gabarito:`B`,explicacao:`O prontuário é essencial como meio de prova, documentando diagnóstico, tratamento e evolução do caso.`},{id:`bioet-098`,topico:`responsabilidade_civil`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`Em caso de erro médico veterinário que resulte na morte do animal, o profissional pode ser responsabilizado:`,alternativas:[`A) Apenas civilmente`,`B) Civilmente (indenização), criminalmente (crime contra a propriedade) e eticamente`,`C) Apenas criminalmente`,`D) Apenas eticamente`,`E) Não há responsabilidade legal por morte animal`],gabarito:`B`,explicacao:`O profissional pode responder nas esferas civil (indenização), criminal (dano qualificado) e ético-disciplinar.`},{id:`bioet-099`,topico:`responsabilidade_civil`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A responsabilidade civil do médico veterinário por erro profissional é:`,alternativas:[`A) Inexistente na legislação brasileira`,`B) Prevista no Código Civil e em legislações específicas`,`C) Aplicável apenas a erros em cirurgias`,`D) Limitada a erros em animais de grande valor`,`E) Exclusivamente administrativa`],gabarito:`B`,explicacao:`A responsabilidade civil profissional é prevista no Código Civil e em legislações específicas, sendo aplicável a qualquer erro.`},{id:`bioet-100`,topico:`responsabilidade_civil`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`A teoria do risco profissional aplicada à veterinária significa que:`,alternativas:[`A) O profissional nunca responde por danos`,`B) O profissional assume os riscos de sua atividade, respondendo objetivamente por danos decorrentes`,`C) Apenas o proprietário assume riscos`,`D) O risco é sempre coberto por seguro`,`E) A teoria não se aplica à veterinária`],gabarito:`B`,explicacao:`Pela teoria do risco profissional, o profissional responde pelos danos decorrentes de sua atividade, independentemente de culpa.`},{id:`bioet-101`,topico:`responsabilidade_civil`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`Para configurar responsabilidade civil do médico veterinário, é necessário comprovar:`,alternativas:[`A) Apenas o dano`,`B) Dano, nexo causal e conduta culposa ou atividade de risco`,`C) Apenas a conduta do profissional`,`D) Apenas o nexo causal`,`E) Apenas a culpa do profissional`],gabarito:`B`,explicacao:`A responsabilidade civil exige a comprovação do dano, nexo causal e conduta culposa (ou atividade de risco na responsabilidade objetiva).`},{id:`bioet-102`,topico:`responsabilidade_civil`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`O médico veterinário que deixa de prestar socorro em caso de urgência:`,alternativas:[`A) Não comete infração`,`B) Pode responder ética, civil e criminalmente por omissão de socorro`,`C) Comete apenas infração administrativa`,`D) Responde apenas se houver contrato de prestação de serviço`,`E) Não há prelegal para essa situação`],gabarito:`B`,explicacao:`A omissão de socorro pode gerar responsabilidade ética, civil (por omissão) e criminal (omissão de socorro).`},{id:`bioet-103`,topico:`responsabilidade_civil`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`A responsabilidade solidária entre profissionais em um hospital veterinário ocorre quando:`,alternativas:[`A) Cada profissional responde apenas por seus atos`,`B) Dois ou mais profissionais participam do mesmo ato danoso, respondendo solidariamente`,`C) Apenas o chefe do serviço responde`,`D) Não existe responsabilidade solidária na veterinária`,`E) Apenas a instituição responde`],gabarito:`B`,explicacao:`Quando múltiplos profissionais contribuem para o dano, todos respondem solidariamente pela indenização.`},{id:`bioet-104`,topico:`responsabilidade_civil`,banca:`CESPE`,ano:2023,dificuldade:`facil`,enunciado:`O seguro de responsabilidade civil profissional do médico veterinário é:`,alternativas:[`A) Obrigatório por lei`,`B) Recomendado como proteção contra reclamações de danos causados durante a atividade profissional`,`C) Proibido pela legislação`,`D) Necessário apenas para cirurgiões`,`E) Desnecessário na prática atual`],gabarito:`B`,explicacao:`O seguro de responsabilidade civil é recomendado como proteção financeira contra eventuais danos profissionais.`},{id:`bioet-105`,topico:`pesquisa_com_animais`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`Todo projeto de pesquisa que utiliza animais deve ser submetido a:`,alternativas:[`A) Apenas ao orientador`,`B) Aprovação da CEUA institucional antes de seu início`,`C) Apenas à coordenação do curso`,`D) Não há necessidade de aprovação ética`,`E) Apenas ao financiador da pesquisa`],gabarito:`B`,explicacao:`Todo projeto com animais deve ter aprovação prévia da Comissão de Ética no Uso de Animais (CEUA).`},{id:`bioet-106`,topico:`pesquisa_com_animais`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`A publicação de resultados de pesquisa com animais que não tenha aprovação da CEUA:`,alternativas:[`A) É aceita por todas as revistas`,`B) Pode ser rejeitada por periódicos científicos e configura infração ética`,`C) Não é relevante para publicação`,`D) É permitida apenas em congressos`,`E) Não há consequências`],gabarito:`B`,explicacao:`Periódicos científicos de qualidade exigem documentação de aprovação ética para aceitar manuscritos.`},{id:`bioet-107`,topico:`pesquisa_com_animais`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`O relatório de atividades com animais (anexo à CEUA) deve conter:`,alternativas:[`A) Apenas o número de animais utilizados`,`B) Informações detalhadas sobre procedimentos, analgesia, eutanásia e destino dos animais`,`C) Apenas o título da pesquisa`,`D) Apenas o nome do pesquisador responsável`,`E) Nenhuma informação específica`],gabarito:`B`,explicacao:`O relatório deve conter informações completas sobre procedimentos, cuidados, analgesia, eutanásia e destino final dos animais.`},{id:`bioet-108`,topico:`pesquisa_com_animais`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`Em pesquisas de campo com animais silvestres, além da CEUA, é necessário:`,alternativas:[`A) Apenas autorização do proprietário do terreno`,`B) Licença do SISBIO/ICMBio para coleta e manipulação de fauna silvestre`,`C) Apenas aprovação da FAPESP`,`D) Não há exigências adicionais`,`E) Apenas autorização da polícia ambiental`],gabarito:`B`,explicacao:`Pesquisas com fauna silvestre exigem licença do SISBIO (Sistema de Autorização e Informação em Biodiversidade).`},{id:`bioet-109`,topico:`pesquisa_com_animais`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`O conceito de "endpoint" em experimentação animal refere-se:`,alternativas:[`A) Ao final cronológico do experimento`,`B) Aos critérios objetivos que determinam quando um animal deve ser retirado do estudo para evitar sofrimento`,`C) Ao resultado estatístico esperado`,`D) À conclusão do relatório`,`E) Ao número de animais no grupo controle`],gabarito:`B`,explicacao:`O endpoint são critérios pré-definidos que indicam quando o animal deve ser sacrificado ou retirado para evitar sofrimento.`},{id:`bioet-110`,topico:`pesquisa_com_animais`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`A utilização de placebo em pesquisas com animais:`,alternativas:[`A) É sempre proibida`,`B) Pode ser utilizada quando cientificamente justificada e com controle adequado da dor`,`C) É obrigatória em todos os estudos`,`D) Não é regulamentada`,`E) É permitida apenas em estudos de campo`],gabarito:`B`,explicacao:`O uso de placebo é aceito quando cientificamente necessário, desde que haja controle adequado do sofrimento.`},{id:`bioet-111`,topico:`pesquisa_com_animais`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`A integridade científica em pesquisa com animais exige:`,alternativas:[`A) Apenas resultados positivos`,`B) Transparência nos métodos, relato honesto dos resultados e disponibilização dos dados`,`C) Publicação apenas de resultados favoráveis`,`D) Não compartilhar dados com outros pesquisadores`,`E) Ignorar resultados negativos`],gabarito:`B`,explicacao:`A integridade científica exige transparência, honestidade e compartilhamento de dados e métodos.`},{id:`bioet-112`,topico:`pesquisa_com_animais`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A lista de animais de uso proibido em pesquisa, conforme a legislação brasileira, inclui:`,alternativas:[`A) Todos os animais são permitidos`,`B) Cães e gatos comunitários (sem proprietário), conforme Lei 14.064/2020`,`C) Apenas animais silvestres`,`D) Apenas primatas`,`E) Não existe lista de proibição`],gabarito:`B`,explicacao:`A Lei 14.064/2020 proíbe a utilização de cães e gatos em pesquisa, salvo em condições específicas.`},{id:`bioet-113`,topico:`pesquisa_com_animais`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`O processo de revisão ética de projetos de pesquisa com animais pela CEUA inclui:`,alternativas:[`A) Apenas análise do orçamento`,`B) Avaliação da justificativa científica, dos métodos, do número de animais e do manejo da dor`,`C) Apenas verificação da formação do pesquisador`,`D) Análise apenas do currículo do orientador`,`E) Não há processo formal de revisão`],gabarito:`B`,explicacao:`A CEUA avalia a relevância científica, os métodos propostos, o número adequado de animais e o manejo de dor/sofrimento.`},{id:`bioet-114`,topico:`pesquisa_com_animais`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`A biossegurança em pesquisa com animais envolve:`,alternativas:[`A) Apenas uso de equipamentos de proteção individual`,`B) Conjunto de medidas para proteger pesquisadores, animais e o meio ambiente de riscos biológicos`,`C) Apenas controle de pragas`,`D) Apenas desinfecção de ambientes`,`E) Não é relevante em pesquisa veterinária`],gabarito:`B`,explicacao:`A biossegurança em pesquisa abrange proteção de pesquisadores, animais e meio ambiente contra riscos biológicos.`},{id:`bioet-115`,topico:`pesquisa_com_animais`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`Sobre a experimentação animal no contexto da pandemia de COVID-19:`,alternativas:[`A) A experimentação foi proibida`,`B) Houve aumento na demanda por modelos animais para pesquisa de vacinas e tratamentos`,`C) Não houve necessidade de modelos animais`,`D) Apenas modelos computacionais foram utilizados`,`E) A OMS proibiu experimentação animal para COVID-19`],gabarito:`B`,explicacao:`A pandemia aumentou significativamente a demanda por modelos animais para desenvolvimento de vacinas e terapias.`},{id:`bioet-116`,topico:`pesquisa_com_animais`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`A reprodutibilidade em pesquisa com animais é importante porque:`,alternativas:[`A) Permite publicar mais artigos`,`B) Garante que os resultados sejam válidos e verificáveis por outros pesquisadores`,`C) Aumenta o custo da pesquisa`,`D) É exigência apenas de revistas estrangeiras`,`E) Não é relevante para a ciência`],gabarito:`B`,explicacao:`A reprodutibilidade é essencial para a validação científica, permitindo que resultados sejam verificados independentemente.`},{id:`bioet-117`,topico:`ensino_com_animais`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`O uso de animais em atividades didáticas no ensino de Medicina Veterinária:`,alternativas:[`A) É livre e não há regulamentação`,`B) Deve seguir normas éticas e utilizar alternativas sempre que possível`,`C) É proibido em todo o território nacional`,`D) Não é necessário aprovação da CEUA`,`E) Pode ser feito sem supervisão docente`],gabarito:`B`,explicacao:`O uso de animais em ensino deve respeitar normas éticas e priorizar métodos alternativos quando disponíveis.`},{id:`bioet-118`,topico:`ensino_com_animais`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`Os simuladores e modelos didáticos como alternativa ao uso de animais vivos em ensino:`,alternativas:[`A) São proibidos por lei`,`B) Devem ser utilizados sempre que possível, reduzindo o uso de animais vivos`,`C) São ineficazes para o aprendizado`,`D) Não substituem o uso de animais em nenhuma situação`,`E) São obrigatórios apenas em universidades públicas`],gabarito:`B`,explicacao:`Simuladores e modelos devem ser priorizados, reduzindo a necessidade de uso de animais vivos em atividades didáticas.`},{id:`bioet-119`,topico:`ensino_com_animais`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`A Lei 11.794/2008 sobre uso de animais em ensino estabelece que:`,alternativas:[`A) O uso de animais em ensino é proibido`,`B) Devem ser utilizados métodos alternativos sempre que disponíveis, com supervisão da CEUA`,`C) Qualquer animal pode ser utilizado sem restrição`,`D) Apenas animais mortos podem ser utilizados`,`E) Não há regulamentação específica para ensino`],gabarito:`B`,explicacao:`A lei determina priorização de métodos alternativos e supervisão da CEUA para uso de animais em ensino.`},{id:`bioet-120`,topico:`ensino_com_animais`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`O conceito de "ciclo de uso" em atividades didáticas com animais refere-se a:`,alternativas:[`A) O tempo de vida do animal`,`B) A limitação do número de vezes que um animal pode ser submetido a procedimentos didáticos`,`C) O período letivo`,`D) A frequência das aulas práticas`,`E) O tempo de recuperação entre procedimentos`],gabarito:`B`,explicacao:`O ciclo de uso limita a exposição do animal a procedimentos didáticos, respeitando seu bem-estar.`},{id:`bioet-121`,topico:`ensino_com_animais`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`Em aulas práticas de cirurgia veterinária, o uso de animais:`,alternativas:[`A) É proibido em qualquer circunstância`,`B) Deve ser gradual, começando com simuladores e progredindo para animais sob supervisão adequada`,`C) Pode ser feito sem anestesia`,`D) Não requer consentimento do proprietário quando são animais de instituição`,`E) É obrigatório o uso de animais vivos`],gabarito:`B`,explicacao:`O ensino cirúrgico deve ser progressivo, com uso de simuladores iniciais e animais sob supervisão e cuidados adequados.`},{id:`bioet-122`,topico:`ensino_com_animais`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`Os animais utilizados em atividades didáticas após o término das atividades:`,alternativas:[`A) Devem ser sacrificados`,`B) Devem ter destino definido, podendo ser mantidos em boas condições ou adotados`,`C) Podem ser abandonados`,`D) Não há regulamentação sobre destino`,`E) Devem ser devolvidos ao fornecedor`],gabarito:`B`,explicacao:`O destino dos animais deve ser definido previamente, garantindo seu bem-estar após o uso didático.`},{id:`bioet-123`,topico:`ensino_com_animais`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`A utilização de cadáveres de animais em ensino anatômico:`,alternativas:[`A) É proibida por questões éticas`,`B) É aceita eticamente quando obtidos de forma legal e com respeito à dignidade do animal`,`C) Não requer nenhum cuidado especial`,`D) Pode usar cadáveres de qualquer origem`,`E) É obrigatória em todas as disciplinas`],gabarito:`B`,explicacao:`O uso de cadáveres é aceito quando obtidos de forma legal e com respeito à dignidade, evitando desperdício.`},{id:`bioet-124`,topico:`ensino_com_animais`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`O uso de animais em demonstrações clínicas para alunos:`,alternativas:[`A) Não necessita de supervisão`,`B) Deve ser supervisionado por médico veterinário responsável`,`C) Pode ser realizado por alunos do último ano sem orientação`,`D) É proibido em cursos de graduação`,`E) Não requer anestesia`],gabarito:`B`,explicacao:`Toda atividade didática com animais deve ter supervisão de profissional habilitado.`},{id:`bioet-125`,topico:`ensino_com_animais`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`A Lei 14.064/2020 que proíbe testes em cães e gatos:`,alternativas:[`A) Proíbe qualquer uso de cães e gatos em ensino`,`B) Proíbe testes de toxicidade, mas permite uso em ensino clínico supervisionado`,`C) Não há exceções`,`D) Aplica-se apenas a cães`,`E) Não é vigente`],gabarito:`B`,explicacao:`A lei proíbe testes de toxicidade em cães e gatos, mas permite uso em ensino clínico supervisionado.`},{id:`bioet-126`,topico:`ensino_com_animais`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`A tecnologia de realidade virtual aplicada ao ensino veterinário:`,alternativas:[`A) É ineficaz para aprendizado`,`B) É uma alternativa promissora que pode reduzir significativamente o uso de animais vivos`,`C) Não é utilizada em nenhum curso`,`D) É obrigatória por lei`,`E) Substitui completamente o uso de animais`],gabarito:`B`,explicacao:`A realidade virtual é uma ferramenta alternativa promissora para o ensino, reduzindo a necessidade de animais vivos.`},{id:`bioet-127`,topico:`ensino_com_animais`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`A obtenção de animais para uso didático deve:`,alternativas:[`A) Incentivar a compra de animais de qualquer fonte`,`B) Priorizar fontes éticas, como animais destinados a abate ou doações, evitando comércio irregular`,`C) Ser feita exclusivamente por compra em pet shops`,`D) Não há regulamentação sobre aquisição`,`E) Permitir captura de animais selvagens`],gabarito:`B`,explicacao:`A aquisição de animais para ensino deve priorizar fontes éticas e regulares, evitando comércio irregular.`},{id:`bioet-128`,topico:`ensino_com_animais`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`O conceito de "redução" aplicado ao ensino veterinário significa:`,alternativas:[`A) Eliminar completamente o uso de animais`,`B) Reduzir o número de animais necessários por turma, compartilhando recursos`,`C) Usar animais menores`,`D) Reduzir o tempo de aula`,`E) Reduzir o número de alunos por turma`],gabarito:`B`,explicacao:`A redução no ensino significa diminuir o número de animais necessários, compartilhando práticas entre alunos.`},{id:`bioet-129`,topico:`relacao_medico_proprietario`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`A comunicação efetiva entre médico veterinário e proprietário é essencial porque:`,alternativas:[`A) Apenas para fins comerciais`,`B) Garante que o proprietário compreenda o diagnóstico, tratamento e decisões sobre o animal`,`C) Não é relevante para o tratamento`,`D) Serve apenas para cobrar honorários`,`E) É obrigatória apenas em hospitais públicos`],gabarito:`B`,explicacao:`A comunicação efetiva é fundamental para que o proprietário compreenda a situação e participe das decisões.`},{id:`bioet-130`,topico:`relacao_medico_proprietario`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`A empatia na relação médico veterinário-proprietário:`,alternativas:[`A) Não é necessária na prática veterinária`,`B) Contribui para melhor adesão ao tratamento e satisfação do proprietário`,`C) Pode prejudicar a objetividade profissional`,`D) É dispensável em casos de emergência`,`E) Deve ser evitada para manter distanciamento`],gabarito:`B`,explicacao:`A empatia melhora a relação profissional, facilita a comunicação e aumenta a adesão ao tratamento.`},{id:`bioet-131`,topico:`relacao_medico_proprietario`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`Os limites da relação médico veterinário-proprietário incluem:`,alternativas:[`A) Não há limites definidos`,`B) Manter profissionalismo, respeitar a privacidade e não explorar a relação para benefício pessoal`,`C) Apenas limites financeiros`,`D) Estabelecer amizade pessoal com todos os clientes`,`E) Compartilhar informações de outros clientes`],gabarito:`B`,explicacao:`O profissional deve manter limites claros, preservando o profissionalismo e a privacidade.`},{id:`bioet-132`,topico:`relacao_medico_proprietario`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`Em caso de erro profissional, o médico veterinário deve:`,alternativas:[`A) Ocultar o erro do proprietário`,`B) Comunicar ao proprietário de forma transparente, assumindo responsabilidade e propondo correção`,`C) Culpar o proprietário pelo erro`,`D) Não documentar o ocorrido`,`E) Transferir o caso sem explicação`],gabarito:`B`,explicacao:`A transparência e a honestidade são fundamentais, mesmo em situações de erro profissional.`},{id:`bioet-133`,topico:`relacao_medico_proprietario`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`A comunicação de más notícias ao proprietário (ex: diagnóstico de doença terminal) deve:`,alternativas:[`A) Ser evitada para não causar sofrimento`,`B) Ser feita com sensibilidade, clareza e oferecimento de suporte`,`C) Ser delegada a auxiliares`,`D) Ser feita apenas por telefone`,`E) Incluir sempre promessas de cura`],gabarito:`B`,explicacao:`A comunicação de más notícias deve ser feita com empatia, clareza e oferecimento de suporte ao proprietário.`},{id:`bioet-134`,topico:`relacao_medico_proprietario`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`A confiança do proprietário no médico veterinário é construída por meio de:`,alternativas:[`A) Promessas de cura`,`B) Transparência, competência profissional e comunicação clara`,`C) Cobrança de honorários elevados`,`D) Publicidade agressiva`,`E) Evitar informar sobre riscos`],gabarito:`B`,explicacao:`A confiança é resultado de transparência, demonstração de competência e comunicação efetiva.`},{id:`bioet-135`,topico:`relacao_medico_proprietario`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`Quando o proprietário apresenta dificuldade em compreender informações técnicas:`,alternativas:[`A) O profissional deve simplificar a linguagem e utilizar analogias para facilitar o entendimento`,`B) Deve ignorar a dificuldade`,`C) Deve fornecer apenas termos técnicos`,`D) Deve encaminhar a outro profissional`,`E) Deve usar apenas comunicação escrita`],gabarito:`A`,explicacao:`O profissional deve adaptar a linguagem, usando termos acessíveis e analogias para garantir a compreensão.`},{id:`bioet-136`,topico:`relacao_medico_proprietario`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`A relação médico veterinário-proprietário deve ser baseada em:`,alternativas:[`A) Hierarquia rígida`,`B) Respeito mútuo, confiança e comunicação transparente`,`C) Superioridade do profissional`,`D) Indiferença`,`E) Interesses financeiros apenas`],gabarito:`B`,explicacao:`A relação deve ser pautada em respeito, confiança e comunicação transparente.`},{id:`bioet-137`,topico:`relacao_medico_proprietario`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`O follow-up (acompanhamento pós-atendimento) é importante na relação médico-proprietário porque:`,alternativas:[`A) Apenas para cobrar novas consultas`,`B) Demonstra cuidado com o paciente, permite ajustes no tratamento e fortalece a confiança`,`C) Não é necessário`,`D) É obrigatório apenas para casos cirúrgicos`,`E) Serve apenas para fins estatísticos`],gabarito:`B`,explicacao:`O acompanhamento demonstra compromisso com o bem-estar do animal e fortalece a relação de confiança.`},{id:`bioet-138`,topico:`relacao_medico_proprietario`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`A recusa do proprietário em seguir as orientações do profissional:`,alternativas:[`A) Deve ser ignorada`,`B) Deve ser compreendida e o profissional deve buscar alternativas ou reforçar a orientação`,`C) Gera responsabilidade criminal para o proprietário`,`D) Permite que o profissional abandone o caso`,`E) Não há impacto no tratamento`],gabarito:`B`,explicacao:`O profissional deve compreender as razões da recusa e buscar alternativas viáveis para o tratamento.`},{id:`bioet-139`,topico:`relacao_medico_proprietario`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`A mediação de conflitos na relação médico veterinário-proprietário pode envolver:`,alternativas:[`A) Apenas ação judicial`,`B) Mediação por terceiros, como conselhos profissionais ou câmaras de mediação`,`C) Não há mecanismos de mediação`,`D) Apenas negociação direta`,`E) Apenas resolução por meio de violência`],gabarito:`B`,explicacao:`Existem mecanismos de mediação disponíveis, incluindo conselhos profissionais e câmaras de mediação.`},{id:`bioet-140`,topico:`relacao_medico_proprietario`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`A responsabilidade de comunicar o diagnóstico ao proprietário é:`,alternativas:[`A) Do auxiliar veterinário`,`B) Exclusiva do médico veterinário responsável pelo caso`,`C) Da recepção`,`D) Do proprietário deve descobrir por conta própria`,`E) Não é obrigatória`],gabarito:`B`,explicacao:`O médico veterinário responsável tem o dever de comunicar diagnósticos e prognósticos ao proprietário.`},{id:`bioet-141`,topico:`bioetica_ambiental`,banca:`ENAV`,ano:2023,dificuldade:`facil`,enunciado:`A bioética ambiental na veterinária está relacionada a:`,alternativas:[`A) Apenas tratamento de animais domésticos`,`B) Considerações éticas sobre impacto ambiental das atividades veterinárias e pecuárias`,`C) Apenas questões financeiras`,`D) Não há relação entre veterinária e meio ambiente`,`E) Apenas regulamentação de frigoríficos`],gabarito:`B`,explicacao:`A bioética ambiental considera as implicações éticas das atividades veterinárias e pecuárias sobre o meio ambiente.`},{id:`bioet-142`,topico:`bioetica_ambiental`,banca:`CESPE`,ano:2022,dificuldade:`medio`,enunciado:`O descarte inadequado de medicamentos veterinários pode causar:`,alternativas:[`A) Nenhum impacto ambiental`,`B) Contaminação do solo, água e cadeia alimentar`,`C) Apenas problemas econômicos`,`D) Benefícios para o ecossistema`,`E) Apenas problemas estéticos`],gabarito:`B`,explicacao:`O descarte inadequado contamina recursos naturais e pode afetar a saúde humana e animal.`},{id:`bioet-143`,topico:`bioetica_ambiental`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`A sustentabilidade na pecuária envolve:`,alternativas:[`A) Apenas maximização do lucro`,`B) Práticas que equilibrem produção, bem-estar animal e preservação ambiental`,`C) Eliminação total da atividade pecuária`,`D) Não há relação entre pecuária e sustentabilidade`,`E) Apenas uso de tecnologia`],gabarito:`B`,explicacao:`A pecuária sustentável busca equilibrar produção, bem-estar animal e preservação ambiental.`},{id:`bioet-144`,topico:`bioetica_ambiental`,banca:`VUNESP`,ano:2022,dificuldade:`dificil`,enunciado:`O uso de antimicrobianos na pecuária como promotores de crescimento:`,alternativas:[`A) Não apresenta riscos ambientais`,`B) Contribui para a seleção de microrganismos resistentes, impactando saúde pública e meio ambiente`,`C) É recomendado pela OMS`,`D) Não há regulamentação`,`E) É proibido apenas em países europeus`],gabarito:`B`,explicacao:`O uso indiscriminado de antimicrobianos contribui para resistência bacteriana, com impacto na saúde pública e ambiental.`},{id:`bioet-145`,topico:`bioetica_ambiental`,banca:`AVAMEC`,ano:2023,dificuldade:`medio`,enunciado:`A fauna silvestre brasileira é protegida por:`,alternativas:[`A) Apenas convenções internacionais`,`B) Legislação ambiental (Lei 9.605/1998, SISBIO) e código florestal`,`C) Não há proteção legal`,`D) Apenas por ONGs ambientalistas`,`E) Apenas em unidades de conservação`],gabarito:`B`,explicacao:`A fauna silvestre é protegida por legislação ambiental federal, incluindo a Lei de Crimes Ambientais e regulamentos do SISBIO.`},{id:`bioet-146`,topico:`bioetica_ambiental`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`O médico veterinário que atende animais silvestres deve:`,alternativas:[`A) Não se preocupar com a origem do animal`,`B) Verificar a procedência legal do animal e comunicar às autoridades quando necessário`,`C) Aceitar qualquer animal sem questionar`,`D) Não há regulamentação específica`,`E) Recusar-se a atender animais silvestres`],gabarito:`B`,explicacao:`O profissional deve verificar a legalidade da posse e comunicar irregularidades às autoridades competentes.`},{id:`bioet-147`,topico:`bioetica_ambiental`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`O impacto ambiental da produção de ração animal envolve:`,alternativas:[`A) Nenhum impacto significativo`,`B) Desmatamento, uso de água, emissão de gases de efeito estreito e uso de antibióticos`,`C) Apenas custo financeiro`,`D) Benefícios exclusivos ao meio ambiente`,`E) Apenas questões de transporte`],gabarito:`B`,explicacao:`A produção de ração tem impactos ambientais significativos que devem ser considerados em decisões éticas.`},{id:`bioet-148`,topico:`bioetica_ambiental`,banca:`UNESP`,ano:2022,dificuldade:`facil`,enunciado:`O descarte correto de carcaças de animais é importante para:`,alternativas:[`A) Apenas estética`,`B) Prevenção de contaminação ambiental e doenças`,`C) Apenas cumprimento de normas`,`D) Não há importância`,`E) Apenas em áreas urbanas`],gabarito:`B`,explicacao:`O descarte correto previne contaminação do solo, água e disseminação de patógenos.`},{id:`bioet-149`,topico:`bioetica_ambiental`,banca:`USP`,ano:2023,dificuldade:`medio`,enunciado:`A medicina veterinária de conservação:`,alternativas:[`A) Não existe como especialidade`,`B) Atua na proteção de espécies ameaçadas e na saúde de ecossistemas`,`C) Foca apenas em animais domésticos`,`D) Não tem relação com ética`,`E) É uma atividade exclusiva de biólogos`],gabarito:`B`,explicacao:`A veterinária de conservação atua na proteção da biodiversidade, saúde de fauna silvestre e ecossistemas.`},{id:`bioet-150`,topico:`bioetica_ambiental`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`A introdução de espécies exóticas no Brasil:`,alternativas:[`A) Não apresenta riscos ambientais`,`B) Pode causar desequilíbrio ecológico e ameaçar espécies nativas`,`C) É incentivada pelo governo`,`D) Não há regulamentação`,`E) Apenas afeta a economia`],gabarito:`B`,explicacao:`Espécies exóticas podem causar desequilíbrio ecológico, competindo com espécies nativas.`},{id:`bioet-151`,topico:`bioetica_ambiental`,banca:`MAPA`,ano:2023,dificuldade:`dificil`,enunciado:`A responsabilidade do médico veterinário com a biossegurança inclui:`,alternativas:[`A) Apenas proteção individual`,`B) Prevenção de disseminação de patógenos entre animais, humanos e meio ambiente`,`C) Não há responsabilidade ambiental`,`D) Apenas controle de pragas em propriedades`,`E) Apenas uso de vacinas`],gabarito:`B`,explicacao:`A biossegurança veterinária envolve prevenção de disseminação de doenças em todas as interfaces.`},{id:`bioet-152`,topico:`bioetica_ambiental`,banca:`ENAV`,ano:2022,dificuldade:`medio`,enunciado:`O conceito "One Health" (Saúde Única) reconhece que:`,alternativas:[`A) Saúde humana, animal e ambiental são independentes`,`B) Saúde humana, animal e ambiental estão interconectadas e devem ser abordadas integradamente`,`C) Apenas a saúde humana é relevante`,`D) Apenas a saúde animal importa`,`E) O meio ambiente não afeta a saúde`],gabarito:`B`,explicacao:`One Health reconhece a interconexão entre saúde humana, animal e ambiental.`},{id:`bioet-153`,topico:`dilemas_contemporaneos`,banca:`ENAV`,ano:2023,dificuldade:`medio`,enunciado:`A terapia gênica em animais:`,alternativas:[`A) Não apresenta questões éticas`,`B) Levanta questões sobre manipulação genética, bem-estar animal e impactos ecológicos`,`C) É proibida em todo o mundo`,`D) Não é regulamentada`,`E) Não tem aplicação na veterinária`],gabarito:`B`,explicacao:`A terapia gênica em animais levanta questões éticas sobre manipulação genética e seus impactos.`},{id:`bioet-154`,topico:`dilemas_contemporaneos`,banca:`CESPE`,ano:2022,dificuldade:`dificil`,enunciado:`A clonagem de animais de estimação:`,alternativas:[`A) É proibida no Brasil`,`B) Não há regulamentação específica no Brasil, mas levanta questões sobre bem-estar e identidade do animal`,`C) É regulamentada pelo MAPA`,`D) Não apresenta questões éticas`,`E) É incentivada pelo CFMV`],gabarito:`B`,explicacao:`A clonagem de pets não tem regulamentação específica no Brasil e levanta questões éticas complexas.`},{id:`bioet-155`,topico:`dilemas_contemporaneos`,banca:`FCC`,ano:2023,dificuldade:`medio`,enunciado:`Os organismos geneticamente modificados (OGMs) na produção animal:`,alternativas:[`A) Não existem na pecuária`,`B) Levantam debates sobre segurança alimentar, impacto ambiental e bem-estar animal`,`C) São unanimemente aceitos`,`D) Não há regulamentação`,`E) São proibidos em todo o mundo`],gabarito:`B`,explicacao:`OGMs animais geram debates sobre segurança, impactos ambientais e considerações éticas.`},{id:`bioet-156`,topico:`dilemas_contemporaneos`,banca:`VUNESP`,ano:2022,dificuldade:`medio`,enunciado:`A edição genética CRISPR-Cas9 aplicada a animais:`,alternativas:[`A) Não tem aplicação veterinária`,`B) Pode ser usada para melhorar resistência a doenças, mas levanta questões éticas sobre limites da manipulação`,`C) É proibida por convenções internacionais`,`D) Não apresenta riscos`,`E) Não é regulamentada`],gabarito:`B`,explicacao:`A edição genética tem potencial para melhorar saúde animal, mas os limites éticos são debatidos.`},{id:`bioet-157`,topico:`dilemas_contemporaneos`,banca:`AVAMEC`,ano:2023,dificuldade:`dificil`,enunciado:`O uso de animais em entretenimento (circos, zoológicos) envolve dilemas éticos sobre:`,alternativas:[`A) Apenas entretenimento`,`B) Bem-estar animal, direitos dos animais, conservação e regulamentação de uso`,`C) Apenas questões econômicas`,`D) Não há dilemas`,`E) Apenas questões de tradição`],gabarito:`B`,explicacao:`O uso de animais em entretenimento envolve múltiplas questões éticas que são debatidas atualmente.`},{id:`bioet-158`,topico:`dilemas_contemporaneos`,banca:`CRMV`,ano:2022,dificuldade:`medio`,enunciado:`A regulamentação sobre posse de animais exóticos no Brasil:`,alternativas:[`A) Permite a posse de qualquer animal`,`B) Exige licença ambiental (IBAMA/SISBIO) e proíbe posse irregular`,`C) Não há regulamentação`,`D) É aplicada apenas em casos comerciais`,`E) Permite apenas para pesquisadores`],gabarito:`B`,explicacao:`A posse de animais exóticos é regulamentada pelo IBAMA e exige licenciamento ambiental.`},{id:`bioet-159`,topico:`dilemas_contemporaneos`,banca:`UFMG`,ano:2023,dificuldade:`dificil`,enunciado:`A inteligência artificial aplicada à medicina veterinária:`,alternativas:[`A) Não levanta questões éticas`,`B) Levanta questões sobre responsabilidade profissional, privacidade de dados e substituição do julgamento clínico`,`C) Substituirá completamente o médico veterinário`,`D) Não tem aplicação prática`,`E) É proibida por conselhos profissionais`],gabarito:`B`,explicacao:`A IA em veterinária levanta questões sobre responsabilidade, privacidade e o papel do profissional.`},{id:`bioet-160`,topico:`dilemas_contemporaneos`,banca:`UNESP`,ano:2022,dificuldade:`medio`,enunciado:`O comércio online de animais:`,alternativas:[`A) É livre e não há regulamentação`,`B) É regulamentado e deve seguir normas de bem-estar e documentação legal`,`C) É proibido em todo o território nacional`,`D) Apenas para espécies domésticas`,`E) Não é fiscalizado`],gabarito:`B`,explicacao:`O comércio de animais online é regulamentado e deve cumprir normas de bem-estar e documentação.`},{id:`bioet-161`,topico:`dilemas_contemporaneos`,banca:`USP`,ano:2023,dificuldade:`dificil`,enunciado:`A medicina veterinária de precisão:`,alternativas:[`A) Não existe`,`B) Utiliza informações genômicas para tratamentos individualizados, levantando questões de acesso e custo`,`C) É acessível a todos`,`D) Não tem base científica`,`E) É proibida`],gabarito:`B`,explicacao:`A veterinária de precisão promete tratamentos personalizados, mas levanta questões de equidade e acesso.`},{id:`bioet-162`,topico:`dilemas_contemporaneos`,banca:`UFRRJ`,ano:2022,dificuldade:`medio`,enunciado:`O uso de drones na veterinária de campo (ex: monitoramento de rebanhos):`,alternativas:[`A) Não levanta questões éticas`,`B) Levanta questões sobre privacidade, bem-estar animal e uso responsável de tecnologia`,`C) É proibido por lei`,`D) Não tem aplicação prática`,`E) Não é regulamentado`],gabarito:`B`,explicacao:`O uso de tecnologia em veterinária levanta questões sobre privacidade e uso responsável.`},{id:`bioet-163`,topico:`dilemas_contemporaneos`,banca:`MAPA`,ano:2023,dificuldade:`medio`,enunciado:`A produção de carne cultivada em laboratório (carne in vitro):`,alternativas:[`A) Não apresenta questões éticas`,`B) Levanta debates sobre bem-estar animal, sustentabilidade, regulamentação e impacto na pecuária tradicional`,`C) É proibida em todos os países`,`D) Não tem base científica`,`E) Não é regulamentada`],gabarito:`B`,explicacao:`A carne cultivada levanta debates sobre bem-estar, sustentabilidade, regulamentação e impacto socioeconômico.`}],i={totalQuestoes:150,distribuicaoPorTopico:{principios_bioeticos:13,etica_profissional:13,experimentacao_animal:13,eutanasia:13,consentimento_informado:13,conflitos_eticos:13,responsabilidade_civil:13,pesquisa_com_animais:12,ensino_com_animais:12,relacao_medico_proprietario:12,bioetica_ambiental:12,dilemas_contemporaneos:11},distribuicaoPorDificuldade:{facil:28,medio:82,dificil:40},distribuicaoPorBanca:{ENAV:23,CESPE:19,FCC:12,VUNESP:12,AVAMEC:12,CRMV:12,UFMG:12,UNESP:12,USP:12,UFRRJ:12,MAPA:12}};export{e as BANCAS,i as ESTATISTICAS_BANCO,r as QUESTOES_BIOETICA,t as TIPOS_PROVA,n as TOPICOS_BIOETICA};